WITH filtered AS (SELECT id, store_name, city, region, sqft, CONCAT_WS('/', region, store_name) AS region_store_name_key FROM stores WHERE LOWER(TRIM(store_name)) = 'riverside'), latest AS (SELECT id, store_name, city, region FROM filtered QUALIFY ROW_NUMBER() OVER (PARTITION BY city ORDER BY sqft NULLS FIRST, id) = 1), with_last AS (SELECT s.*, x.store_sale_revenue, x.store_sale_sale_date FROM latest s LEFT JOIN LATERAL (SELECT c.revenue AS store_sale_revenue, c.sale_date AS store_sale_sale_date FROM store_sales c WHERE c.store_id = s.id ORDER BY c.units DESC, c.id DESC LIMIT 1) x ON TRUE), matched_keys AS (SELECT id, region FROM with_last EXCEPT SELECT id, region FROM stores WHERE opened_date BETWEEN '2023-10-17' AND '2025-07-11'), verified AS (SELECT s.* FROM with_last s INNER JOIN matched_keys k ON s.id = k.id AND s.region = k.region), scored AS (SELECT id, store_name, RANK() OVER (ORDER BY store_sale_revenue DESC) AS store_sale_revenue_rank, DENSE_RANK() OVER (PARTITION BY region, city ORDER BY store_sale_revenue DESC NULLS FIRST) AS store_sale_revenue_dense_rank, DENSE_RANK() OVER (ORDER BY store_sale_revenue NULLS FIRST) AS store_sale_revenue_dense_rank_2 FROM verified), scored_stores AS (SELECT store_sale_revenue_rank, store_sale_revenue_dense_rank_2, DENSE_RANK() OVER w_running AS store_sale_revenue_dense_rank_dense_rank, DENSE_RANK() OVER (ORDER BY store_sale_revenue_rank DESC) AS store_sale_revenue_rank_dense_rank, DENSE_RANK() OVER (ORDER BY store_sale_revenue_dense_rank_2) AS store_sale_revenue_dense_rank_2_dense_rank, RANK() OVER w_part AS store_sale_revenue_dense_rank_2_rank FROM scored WHERE store_sale_revenue_dense_rank_2 BETWEEN 5 AND 6 WINDOW w_running AS (ORDER BY store_sale_revenue_dense_rank), w_part AS (ORDER BY store_sale_revenue_dense_rank_2 DESC)), with_windows AS (SELECT store_sale_revenue_dense_rank_2, store_sale_revenue_rank_dense_rank, DENSE_RANK() OVER (ORDER BY store_sale_revenue_dense_rank_2 DESC) AS store_sale_revenue_dense_rank_2_dense_rank_2 FROM scored_stores) SELECT CASE WHEN store_sale_revenue_rank_dense_rank >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END AS store_sale_revenue_rank_dense_rank_tier, MIN(store_sale_revenue_dense_rank_2) AS min_store_sale_revenue_dense_rank_2, APPROX_PERCENTILE(store_sale_revenue_dense_rank_2, ARRAY(0.25, 0.5, 0.75)) AS store_sale_revenue_dense_rank_2_quartiles, COUNT(*) AS row_count FROM with_windows GROUP BY store_sale_revenue_rank_dense_rank_tier ORDER BY store_sale_revenue_rank_dense_rank_tier DESC
